sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const expandedItem = api.state.expandedInfo.expandedItem;
    let data = [{
            "label": helpers.translateSync("Description"),
            "value": {
                "type": "string",
                "value": expandedItem.description ? expandedItem.description : '-',
            }
        }, {
            "label": helpers.translateSync("Entity"),
            "value": {
                "type": "string",
                "value": expandedItem.entityName,
            }
        },
        {
            "label": helpers.translateSync("State"),
            "value": {
                "type": "string",
                "value": expandedItem.stateDispalyValue
            }
        }, {
            "label": helpers.translateSync("Event type"),
            "value": {
                "type": "string",
                "value": expandedItem.eventTypeDisplayValue
            }
        },{
            "label": helpers.translateSync("Sub type"),
            "value": {
                "type": "string",
                "value": expandedItem.subType
            }
        }
    ];

    if (expandedItem.eventType == "1") {
        const financialData = [{
            "label": helpers.translateSync("Gross loss"),
            "value": {
                "type": "string",
                "value": expandedItem.grossLoss
            }
        }, {
            "label": helpers.translateSync("Net loss"),
            "value": {
                "type": "string",
                "value": expandedItem.netLoss
            }
        }];
        data = [...data, ...financialData];
    }

    const remainingData = [{
        "label": helpers.translateSync("Non financial impact"),
        "value": {
            "type": "string",
            "value": expandedItem.nonFinancialImpact ? expandedItem.nonFinancialImpact : helpers.translateSync("None"),
        }
    }, {
        "label": helpers.translateSync("Date of discovery"),
        "value": {
            "type": "string",
            "value": expandedItem.dateOfDiscovery
        }
    }, {
        "label": helpers.translateSync("Category"),
        "value": {
            "type": "string",
            "value": expandedItem.category
        }
    }];

    data =  [...data, ...remainingData];
    return data;
}
